		return
	}
	if err := syncDir("."); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	if v == nil {
		delete(s.values, k)
	} else {
		s.values[k] = *v
	}
	fmt.Fprint(w, "OK")
}
